local DSP = require "ejoysdk_lua.protocal.ejoysdk_ds_protocal"

local M = {}

function M.get_community_info(scene, cb)
    -- 如果游戏不支持直接下载显示二维码，那就调ejoysdk_file.download_file自己下
    DSP.post(DSP.SERVICE.GAME_COMMUNITY_INFO, { sceneCode = scene }, cb)
end

return M